def check_inclusion(s1, s2):
    k = len(s1)
    if k > len(s2):
        return False
    diff = [0] * 26                    # count(s1) - count(window)
    for c in s1:
        diff[ord(c) - 97] += 1
    for c in s2[:k]:
        diff[ord(c) - 97] -= 1
    matched = sum(d == 0 for d in diff)

    def update(i, delta):
        nonlocal matched
        if diff[i] == 0:
            matched -= 1
        diff[i] += delta
        if diff[i] == 0:
            matched += 1

    for r in range(k, len(s2)):
        if matched == 26:
            return True
        update(ord(s2[r]) - 97, -1)      # letter entering
        update(ord(s2[r - k]) - 97, +1)  # letter leaving
    return matched == 26

