def check_inclusion(s1, s2):
    k = len(s1)
    if k > len(s2):
        return False
    need, window = [0] * 26, [0] * 26
    for c in s1:
        need[ord(c) - 97] += 1
    for c in s2[:k]:
        window[ord(c) - 97] += 1
    if window == need:
        return True
    for r in range(k, len(s2)):
        window[ord(s2[r]) - 97] += 1
        window[ord(s2[r - k]) - 97] -= 1
        if window == need:             # 26 comparisons on every slide
            return True
    return False
